import sys
import re
import time
import math
from typing import List, Tuple, Optional

def evaluate_expression(expr: str) -> int:
    try:
        return int(eval(expr))
    except ZeroDivisionError:
        raise ValueError("integer division or modulo by zero")
    except Exception as e:
        raise ValueError(f"invalid expression: {str(e)}")

def process_line(line: str, line_num: int) -> Tuple[str, bool]:
    errors_occurred = False
    result = line
    placeholders = re.findall(r'\{\{([^}]+)\}\}', line)

    for i, placeholder in enumerate(placeholders):
        try:
            value = evaluate_expression(placeholder)
            result = result.replace(f'{{{{{placeholder}}}}}', str(value))
        except ValueError as e:
            errors_occurred = True
            result = line
            print(f"line {line_num}: {str(e)}", file=sys.stderr)
            break

    return result, errors_occurred

def main():
    errors_total = 0
    for line_num, line in enumerate(sys.stdin, 1):
        start_time = time.time()
        processed_line, errors = process_line(line.strip(), line_num)
        sys.stdout.write(processed_line + '\n')
        elapsed = time.time() - start_time
        if errors:
            errors_total += 1
        time.sleep(max(0, 0.2 - elapsed))

    if errors_total > 0:
        print(f"errors: {errors_total}", file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
import re
import time

# Regular expression to find placeholders
placeholder_pattern = re.compile(r'{{\s*(.*?)\s*}}')

# Function to evaluate the expression safely
def evaluate_expression(expr):
    try:
        return eval(expr, {'__builtins__': None}, {})
    except Exception as e:
        return str(e)

# Main function to process input
def main():
    error_count = 0
    line_number = 1
    start_time = time.time()

    for line in sys.stdin:
        line = line.rstrip('\n')  # Remove newline character
        placeholders = placeholder_pattern.findall(line)
        results = line

        for placeholder in placeholders:
            result = evaluate_expression(placeholder)
            if isinstance(result, str):  # If it's an error message
                print(f'line {line_number}: {result}', file=sys.stderr)
                error_count += 1
                break
            else:
                results = results.replace(f'{{{{ {placeholder} }}}}', str(result))

        print(results)
        line_number += 1
        # Wait for 200 milliseconds before processing the next line
        time.sleep(0.2)

    if error_count > 0:
        print(f'errors: {error_count}', file=sys.stderr)

if __name__ == '__main__':
    main()
